window.SUBJECTS.push({"id":"env","n":"Environment","tab":"Environment","w":"Ecology, protected areas and biodiversity, pollution and climate.","topics":[{"id":"ecology","n":"Ecology and Sustainability","qs":[{"id":"q0088","q":"Which environmental concept best describes the responsible and ethical use of resources to meet the needs of the present without compromising the ability of future generations to meet their own needs?","o":["Exploitation","Conservation","Overconsumption","Preservation"],"a":1,"x":"Using resources wisely so future generations can also meet their needs is conservation, which is the idea behind sustainable development.","e":"The definition comes from the Brundtland Commission's report 'Our Common Future' (1987).","src":["ASO 18 Aug 2025 S3"]},{"id":"q0249","q":"Which environmental issue, among the following, poses a significant challenge to infrastructure development?","o":["Increase in online commerce","Decline in rural populations","Rapid urbanisation","Unsustainable use of resources"],"a":3,"x":"Unsustainable use of resources — overdrawing groundwater, sand mining, clearing forests — makes infrastructure costlier and less durable.","e":"Sustainable infrastructure uses resources at a rate nature can replenish.","src":["ASO 20 Aug 2025 S2"]},{"id":"q1794","q":"Which of the following comprise the natural environment? I. Land II. Water III. Plants IV. Animals","o":["I and II","II, III and IV","III and IV","I, II, III and IV"],"a":3,"x":"The natural environment includes land, water, air, plants and animals: everything not made by humans.","e":"The human-made environment: buildings, roads, bridges.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q6147","q":"The method of preparing compost with the help of redworms is called__________________ .","o":["biocomposting","vermicomposting","quick composting","redicomposting"],"a":1,"x":"Composting with redworms is called vermicomposting.","e":"","src":["Junior Clerk 9 Nov 2021 S2"]},{"id":"q6955","q":"Water harvesting is called __________ in Himachal Pradesh.","o":["Kulhs","Eris","Bundhis","Kattas"],"a":0,"x":"In Himachal Pradesh, traditional water-harvesting channels are called kuhls.","e":"Eris – Tamil Nadu; Bundhis – Odisha/MP; Kattas – Karnataka.","src":["Stenographer 8 Aug 2021"]},{"id":"q4967","q":"The micro-organisms which convert the dead plants and animals to humus are known as:","o":["bacteria","fungi","protozoa","decomposers"],"a":3,"x":"Decomposers (bacteria and fungi) break dead plants and animals down into humus.","e":"","src":["Personal Assistant 26 Nov 2021 S3"]},{"id":"q4970","q":"The amount of water recommended by the United Nations for drinking, washing, cooking and maintaining proper hygiene is a minimum of ______ litres per person per day.","o":["100","10","35","50"],"a":3,"x":"The UN says each person needs between 50 and 100 litres of water a day for drinking, cooking and hygiene.","e":"","src":["Personal Assistant 26 Nov 2021 S3"]},{"id":"q5410","q":"Which of the following is a type of non-renewable source of energy?","o":["Ethanol","Geothermal","Hydropower","Nuclear"],"a":3,"x":"Nuclear energy uses uranium, which is non-renewable; ethanol, geothermal and hydropower are renewable.","e":"","src":["Personal Assistant 29 Nov 2021 S1"]},{"id":"q9200","q":"The plant group fungi can be categorised in which of the following trophic levels of the ecosystem?","o":["Decomposers","Producers","Apex predators","Primary consumers"],"a":0,"x":"Fungi are decomposers in an ecosystem.","e":"","src":["MTS 8 Mar 2026 S1"]},{"id":"q3595","q":"Which of the following are NOT the consequences of Deforestation?","o":["Increase in temperature level of earth","Increase in pollution level on earth","Extinction of animal species","Increase in groundwater level"],"a":3,"x":"Deforestation raises temperatures and pollution and causes species extinction; it lowers groundwater levels rather than raising them.","e":"","src":["Fire Operator 20 Apr 2021 S1"]},{"id":"q3813","q":"______ is the first state of India which has made rooftop rainwater harvesting structure compulsory to all the houses across state.","o":["Tamil Nadu","Meghalaya","Kerala","Uttarakhand"],"a":0,"x":"Tamil Nadu was the first state to make rooftop rainwater harvesting compulsory for all buildings (2003).","e":"","src":["Fire Operator 22 Apr 2021 S1"]},{"id":"q3912","q":"Which of the following statements are correct regarding 'Biogas'?","o":["Its manufacturing is done in the presence of oxygen","It cannot be produced from sewage","Its starting material is mainly cow-dung","It is an excellent fuel and contains 75 per cent ethane."],"a":2,"x":"Biogas is made mainly from cow dung by anaerobic (oxygen-free) digestion; it can also come from sewage and contains up to about 75% methane.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 22 Nov 2021 S1"]},{"id":"q4622","q":"The study of the relationship between living things and their interactions with their surroundings is called:","o":["Zoology","Geology","Ecology","Biology"],"a":2,"x":"Ecology is the study of how living things interact with each other and their surroundings.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 25 Nov 2021 S2"]},{"id":"q0947","q":"In the context of sustainable development, which principle ensures equal opportunities for all?","o":["Empowerment","Productivity","Equity","Sustainability"],"a":2,"x":"Equity in sustainable development means fair and equal access to resources and opportunities for everyone, now and in future generations.","e":"The three pillars of sustainability: economic, social and environmental.","src":["PRT 18 Feb 2026 S2"]},{"id":"q1167","q":"What is a defining characteristic of a stratified ecosystem?","o":["Horizontal layering of vegetation","Vertical layering of environmental conditions and communities of organisms","Uniform distribution of organisms throughout the ecosystem","Random distribution of nutrients and resources within the ecosystem"],"a":1,"x":"Stratification is the vertical layering of an ecosystem: in a forest, trees, shrubs, herbs and ground layer each have different light and conditions.","e":"Tropical rainforests show the most layers.","src":["PRT 26 Mar 2026 S3"]},{"id":"q1244","q":"In which process do microorganisms break down organic matter into simple compounds, releasing nutrients back into the ecosystem?","o":["Photosynthesis","Respiration","Decomposition","Transpiration"],"a":2,"x":"Decomposition is the breakdown of dead organic matter by bacteria and fungi into simple compounds, returning nutrients to the ecosystem.","e":"Decomposers close the nutrient cycle.","src":["PRT 3 Apr 2026 S2"]},{"id":"q1273","q":"In a food chain, small carnivores or secondary consumers are present in which tropical level?","o":["Trophic level fourth","Trophic level first","Trophic level second","Trophic level third"],"a":3,"x":"In a food chain, producers are the 1st trophic level, herbivores (primary consumers) the 2nd, and small carnivores (secondary consumers) the 3rd.","e":"Grass → grasshopper → frog → snake: the frog is at the 3rd level.","src":["PRT 10 Apr 2026 S1"]},{"id":"q2302","q":"Which of the following is an example of artificial ecosystem?","o":["Crop fields","Forests","Ponds","Lakes"],"a":0,"x":"Crop fields are artificial (human-made) ecosystems; forests, ponds and lakes are natural.","e":"","src":["TGT 13 Sep 2021 S3"]},{"id":"q4701","q":"Trophic level in an ecosystem represents ______.","o":["Oxygen levels","Salt level","Energy level","Water level"],"a":2,"x":"A trophic level is an energy (feeding) level in a food chain.","e":"","src":["TGT 25 Sep 2021 S1"]},{"id":"q5605","q":"In most natural ecosystems, energy is absorbed from the sun and then consumed by producers and so on. What kind of energy flow is this considered as?","o":["Multidirectional","No specific direction","Unidirectional","Bidirectional"],"a":2,"x":"Energy flows in one direction (unidirectional) through an ecosystem: sun → producers → consumers.","e":"","src":["TGT 30 Nov 2021 S1"]},{"id":"q8842","q":"Which type of vegetation in India displays a gradual change in plant types as the altitude increases?","o":["Mangrove forests found in saline delta regions","Thorn forests present in semi-arid regions","Tropical deciduous forests with seasonal leaf fall","Montane forests showing altitude-based succession"],"a":3,"x":"Montane forests change from tropical to temperate to alpine types as altitude rises.","e":"","src":["Special Educator 29 Jun 2025 S1"]},{"id":"q0767","q":"Which ecological concept did Charles Elton introduce in 1927?","o":["Biogeochemical cycle","Dominance hierarchies","Evolutionary ecology","Pyramid of numbers"],"a":3,"x":"Charles Elton introduced the pyramid of numbers (Eltonian pyramid) in 1927, showing how the number of organisms usually falls at each higher trophic level.","e":"A tree ecosystem gives an inverted pyramid of numbers: one tree, many insects.","src":["PGT 25 Sep 2025"]},{"id":"q8089","q":"What is the meaning of gross primary productivity of an ecosystem?","o":["Rate of biomass production","Rate of consumption of inorganic matter","Rate of production of organic matter during photosynthesis","Available biomass for consumption"],"a":2,"x":"Gross primary productivity is the rate at which organic matter is produced by photosynthesis.","e":"","src":["PGT 21 Jun 2023 S1"]},{"id":"q8413","q":"Which of the following can survive in saline water?","o":["Mangrove trees","Thorny bushes","Tropical deciduous forest","Tropical rainforest"],"a":0,"x":"Mangrove trees can survive in saline water.","e":"","src":["PGT 21 Jun 2023 S2"]},{"id":"q8442","q":"Which of the following is an example of a Detritivores?","o":["Earthworm","Crow","Vulture","Fungi"],"a":0,"x":"Earthworms are detritivores that feed on dead organic matter.","e":"","src":["PGT 22 Jun 2023 S1"]},{"id":"q4722","q":"The second trophic level in food chain is occupied by __________.","o":["omnivores","herbivores","carnivores","parasitic"],"a":1,"x":"Herbivores (primary consumers) occupy the second trophic level.","e":"","src":["Laboratory Assistant (HRD Quality Control) 25 Sep 2021 S1"]},{"id":"q5267","q":"Which of the following is NOT an abiotic components of ecosystem?","o":["Temperature","Soil","Rainfall","Plants"],"a":3,"x":"Plants are biotic; temperature, soil and rainfall are abiotic.","e":"","src":["Senior Scientific Assistant (Physics) 27 Sep 2021 S3"]}]},{"id":"biodiversity","n":"Parks, Forests and Biodiversity","qs":[{"id":"q0272","q":"Which of the following Indian states has the lowest percentage of its geographical area under the forest, according to the India State of Forest Report 2021?","o":["Gujarat","Haryana","Rajasthan","Uttar Pradesh"],"a":1,"x":"India State of Forest Report 2021: Haryana had the lowest share of area under forest (about 3.6%).","e":"Highest share: Mizoram (about 84.5%). Largest forest area: Madhya Pradesh.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0341","q":"'Red Sanders' is an endangered tree species found in which of the following states?","o":["West Bengal","Maharashtra","Andhra Pradesh","Rajasthan"],"a":2,"x":"Red Sanders (Pterocarpus santalinus) is endemic to the southern Eastern Ghats of Andhra Pradesh, mainly the Seshachalam hills, and is heavily smuggled for its red wood.","e":"It is listed as Endangered on the IUCN Red List.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0352","q":"Kashmir stag, Spotted deer and Tibetan antelope are found in which of the following forests?","o":["Montane forests","Tropical thorn forests","Mangrove forests","Thorn forests"],"a":0,"x":"Montane (mountain) forests of the Himalaya shelter the Kashmir stag (hangul), spotted deer, Tibetan antelope, wild sheep and yak.","e":"Thorn forests have camels, wild asses and foxes; mangroves have the Royal Bengal tiger and crocodiles.","src":["ASO 21 Aug 2025 S2"]},{"id":"q1608","q":"Which one is not related to the protection of flora and fauna?","o":["Wildlife Sanctuary","National Park","Biosphere Reserve","Amusement Park"],"a":3,"x":"Wildlife sanctuaries, national parks and biosphere reserves protect flora and fauna. An amusement park is for entertainment.","e":"India's first national park: Hailey (now Jim Corbett), 1936.","src":["Patwari 17 Sep 2022 S2"]},{"id":"q0492","q":"In which of the following states is the Jaldapara National Park located?","o":["Tamil Nadu","Kerala","West Bengal","Madhya Pradesh"],"a":2,"x":"Jaldapara National Park is in Alipurduar district of north Bengal, known for the one-horned rhinoceros.","e":"Nearby, Gorumara National Park also has rhinos.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0613","q":"Which among the following national parks is the only national park in which four Big Cats – tiger, leopard, snow leopard and clouded leopard are found?","o":["Narayan National Park","Namdapha National Park","Kaziranga National Park","Dachigam National Park"],"a":1,"x":"Namdapha National Park in Arunachal Pradesh is the only park in India where four big cats — tiger, leopard, snow leopard and clouded leopard — are found.","e":"It is also home to the hoolock gibbon, India's only ape.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S2"]},{"id":"q0653","q":"In which of the following states is the Marine National Park located?","o":["Madhya Pradesh","Maharashtra","Tamil Nadu","Gujarat"],"a":3,"x":"The Marine National Park in the Gulf of Kutch, Jamnagar, Gujarat, was India's first marine national park (1982), known for coral reefs.","e":"Mahatma Gandhi Marine National Park is at Wandoor in the Andaman Islands.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q0692","q":"Which among the following national parks is located in Manipur?","o":["Coringa Wildlife Sanctuary","Keibul Lamjao National Park","Jim Corbett National Park","Nagarhole National Park"],"a":1,"x":"Keibul Lamjao National Park in Manipur is the world's only floating national park, on the phumdis of Loktak Lake, and the home of the sangai (brow-antlered deer).","e":"Nagarhole is in Karnataka; Jim Corbett in Uttarakhand; Coringa is a sanctuary in Andhra Pradesh.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q6778","q":"Gir Wildlife Sanctuary is situated in which of the following states?","o":["Maharashtra","Goa","Andhra Pradesh","Gujarat"],"a":3,"x":"Gir National Park and Wildlife Sanctuary in Gujarat is the only home of the Asiatic lion.","e":"","src":["Junior Assistant 25 Aug 2021"]},{"id":"q2036","q":"Which of the following tree(s) is/are found in tropical evergreen forests? I. Ebony II. Mahogany III. Rosewood","o":["I and II","II and III","I and III","I, II and III"],"a":3,"x":"Tropical evergreen (rain) forests have hardwood trees such as ebony, mahogany and rosewood.","e":"Tropical deciduous forests: teak, sal, sandalwood.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2157","q":"Which of the following type of forests are the most widespread forests in India?","o":["Tropical Thorn forests","Tropical Deciduous forests","Montane forests","Littoral and Swamp Forest"],"a":1,"x":"Tropical deciduous (monsoon) forests are India's most widespread forests; they shed leaves in the dry season. Teak and sal are typical trees.","e":"Moist deciduous: over 100 cm rain; dry deciduous: 70–100 cm.","src":["Junior Clerk 13 Nov 2021 S3"]},{"id":"q2460","q":"On which date is the World Wetlands Day celebrated?","o":["February 1st","February 2nd","February 3rd","February 4th"],"a":1,"x":"World Wetlands Day is observed on 2 February, marking the Ramsar Convention signed on that day in 1971.","e":"Ramsar is in Iran.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2492","q":"Which of the following type of forests are found in the western slope of the Western Ghats, hills of the northeastern region and the Andaman Nicobar Islands?","o":["Tropical Evergreen and Semi Evergreen forests","Montane forests","Tropical thorn forests","Tropical deciduous forests"],"a":0,"x":"Tropical evergreen and semi-evergreen forests grow on the western slopes of the Western Ghats, the north-eastern hills and the Andaman and Nicobar Islands, where rainfall exceeds 200 cm.","e":"Also called tropical rainforests.","src":["Junior Clerk 15 Nov 2021 S3"]},{"id":"q2532","q":"In which of the following states is the Sultanpur National Park situated?","o":["Madhya Pradesh","Rajasthan","Maharashtra","Haryana"],"a":3,"x":"Sultanpur National Park, a bird sanctuary and Ramsar site, is in Gurugram district, Haryana.","e":"Haryana's other park: Kalesar.","src":["Junior Clerk 16 Nov 2021 S1"]},{"id":"q2605","q":"Which of the following statement(s) regarding tropical evergreen forest is/are correct? I. They are also called tropical rainforests. II. The trees of these forests shed leaves completely twice a year.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Tropical evergreen forests are also called tropical rainforests. Their trees do not shed all their leaves at one time, so they stay green all year; statement II is wrong.","e":"Deciduous forests shed leaves in the dry season.","src":["Junior Clerk 16 Nov 2021 S3"]},{"id":"q2673","q":"Which of the following is a biosphere reserve in India? I. Sundarbans II. Nilgiri III. Manas","o":["I and II","II and III","I and III","I, II and III"],"a":3,"x":"Sundarbans (West Bengal), Nilgiri (the first, 1986) and Manas (Assam) are all biosphere reserves in India.","e":"India has 18 biosphere reserves.","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q2874","q":"Which of the following tree is found in tropical deciduous forest? I. Shisham II. Sandalwood","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Shisham (sheesham) and sandalwood are trees of tropical deciduous (monsoon) forests, along with teak, sal and bamboo.","e":"","src":["Junior Clerk 17 Nov 2021 S1"]},{"id":"q1295","q":"How many distinct floristic regions can India be divided into?","o":["7","8","6","5"],"a":1,"x":"India is divided into 8 floristic regions: Western Himalayas, Eastern Himalayas, Assam, Indus plain, Ganga plain, Deccan, Malabar and Andamans (after Chatterjee).","e":"The Eastern Himalayas and Western Ghats are biodiversity hotspots.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1328","q":"Which among the following national parks is not located in West Bengal?","o":["Kanha National Park","Jaldapara National Park","Gorumara National Park","Buxa Tiger Reserve"],"a":0,"x":"Kanha National Park is in Madhya Pradesh. Jaldapara, Gorumara and Buxa Tiger Reserve are in West Bengal.","e":"Kanha inspired Kipling's 'The Jungle Book' and protects the barasingha.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q5010","q":"The region with less than 70 cm of rainfall and found in the north-western part of the country is called:","o":["tropical evergreen forests","tropical thorn forests and scrubs","mangrove forests","montane forests"],"a":1,"x":"Tropical thorn forests and scrubs grow where rainfall is under 70 cm, in north-western India (NCERT Class 9).","e":"","src":["Stenographer 26 Nov 2021 S2"]},{"id":"q6857","q":"Wildlife Protection Act was passed in _________.","o":["1970","1986","1982","1972"],"a":3,"x":"The Wildlife (Protection) Act was passed in 1972.","e":"","src":["Stenographer 14 Aug 2021"]},{"id":"q6911","q":"Biological Diversity Act was passed in ___________.","o":["2005","2002","2000","1995"],"a":1,"x":"The Biological Diversity Act was passed in 2002.","e":"","src":["Stenographer 14 Aug 2021 S2"]},{"id":"q4960","q":"With reference to Wildlife Sanctuaries and National parks of India, in which state is the Valmiki National Park located?","o":["Bihar","Kerala","Gujarat","Uttar Pradesh"],"a":0,"x":"Valmiki National Park and Tiger Reserve is in West Champaran, Bihar.","e":"","src":["Personal Assistant 26 Nov 2021 S3"]},{"id":"q10041","q":"Which of the following tiger reserves has been declared as India’s first Dark Sky Park, offering pristine night sky without light pollution?","o":["Orang Tiger Reserve","Namdapha Tiger Reserve","Kamlang Tiger Reserve","Pench Tiger Reserve"],"a":3,"x":"Pench Tiger Reserve in Maharashtra was declared India's first Dark Sky Park in 2022.","e":"","src":["Assistant Superintendent 20 Jul 2024 S1"]},{"id":"q10066","q":"Which of the following term is used to denote plants of a particular region or period?","o":["Biodiversity","Ecosystem","Fauna","Flora"],"a":3,"x":"Flora means the plants of a particular region or period; fauna means its animals.","e":"","src":["Assistant Superintendent 20 Jul 2024 S1"]},{"id":"q10091","q":"The Kottigehar dancing frog of the Western Ghats falls into which of the following categories of the IUCN threatened species list?","o":["Extinct in the Wild","Vulnerable","Critically Endangered","Least Concern"],"a":2,"x":"The Kottigehar dancing frog of the Western Ghats is listed as Critically Endangered by the IUCN.","e":"","src":["Assistant Superintendent 20 Jul 2024 S2"]},{"id":"q10116","q":"The snow leopard (Panthera uncia) is listed under which schedule of the Wildlife (Protection) Act 1972?","o":["Schedule III","Schedule II","Schedule I","Schedule IV"],"a":2,"x":"The snow leopard is protected under Schedule I of the Wildlife (Protection) Act, 1972.","e":"","src":["Assistant Superintendent 20 Jul 2024 S3"]},{"id":"q8965","q":"Which of the following regions in India is known for Wet Tropical Evergreen Vegetation?","o":["Indo-Gangetic Plains","Western Rajasthan","Southern parts of Western Ghats","Thar Desert"],"a":2,"x":"Wet tropical evergreen forests grow in the southern Western Ghats, the north-east and the Andaman and Nicobar Islands.","e":"","src":["MTS 3 Mar 2026 S2"]},{"id":"q9390","q":"In which of the following states are Mangrove Forests primarily found in India?","o":["West Bengal","Uttar Pradesh","Punjab","Madhya Pradesh"],"a":0,"x":"Of these states, West Bengal has India's main mangrove forests, in the Sundarbans.","e":"","src":["MTS 25 Feb 2026 S3"]},{"id":"q9474","q":"In which of the following states is the Keoladeo National Park located?","o":["Uttar Pradesh","Rajasthan","Uttarakhand","Madhya Pradesh"],"a":1,"x":"Keoladeo National Park (Bharatpur), a UNESCO site known for birds, is in Rajasthan.","e":"","src":["MTS 26 Feb 2026 S3"]},{"id":"q3868","q":"The Dudhwa National Park is located in which of the following states?","o":["Andhra Pradesh","Uttar Pradesh","Gujarat","West Bengal"],"a":1,"x":"Dudhwa National Park is in Lakhimpur Kheri, Uttar Pradesh, on the Nepal border; it is a tiger reserve known for swamp deer.","e":"","src":["Store Keeper 22 Apr 2021 S3"]},{"id":"q3639","q":"Which one of the following tree grows mainly in the western part of the Himalayas and is a highly valued endemic species for its durable wood, mainly used in construction activities?","o":["Silver Firs","Junipers","Deodar","Pines"],"a":2,"x":"The deodar is a highly valued endemic conifer of the western Himalayas, prized for its durable construction wood.","e":"","src":["Fire Operator 20 Apr 2021 S2"]},{"id":"q3681","q":"Which of the following are not a species of Tropical Thorn Forest?","o":["Babool","Ber","Neem","Hura"],"a":3,"x":"Tropical thorn forests have babool, ber, khair, khejri, neem and wild date palm (NCERT); 'hura' is not one of their species.","e":"","src":["Fire Operator 20 Apr 2021 S3"]},{"id":"q3816","q":"Which of the following statement regarding Tropical Deciduous Forest is correct? I. These forests are called monsoon forests. II. Sal, Peepal and Neem are important trees of these forest.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Tropical deciduous forests are called monsoon forests; sal, peepal, neem, teak and shisham are important trees there (NCERT Class 7).","e":"","src":["Fire Operator 22 Apr 2021 S1"]},{"id":"q3271","q":"This is a home to gangetic dolphins and 75 per cent population of critically endangered species gharial.Madhya Pradesh government declares as an Eco - sensitive zone. Name it.","o":["National Chambal Sanctuary","Sariska National Park","Pench National Park","Kanha National Park"],"a":0,"x":"The National Chambal Sanctuary (Rajasthan, MP, UP) protects the critically endangered gharial, the Gangetic dolphin and the red-crowned roof turtle.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 18 Nov 2021 S3"]},{"id":"q3919","q":"Nilgiri Biosphere reserve is spread across different locations. Which of the following are not part of it?","o":["Nagarhole","Siruvani Hills","Nalbari","Silent Valley"],"a":2,"x":"The Nilgiri Biosphere Reserve includes Nagarhole, Bandipur, Mudumalai, Silent Valley and the Siruvani hills; Nalbari is a district of Assam.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 22 Nov 2021 S1"]},{"id":"q4350","q":"Who was known as the Birdman of India?","o":["Chandi Prasad Bhatt","Sunderlal Bahuguna","Salim Ali","Jadav Payeng"],"a":2,"x":"Ornithologist Salim Ali is known as the 'Birdman of India'.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S3"]},{"id":"q4640","q":"The Forest Rights Act, which accords legal recognition to the rights of traditional forest dwelling communities in India was passed in the year:","o":["2000","2002","2006","2008"],"a":2,"x":"The Forest Rights Act, recognising the rights of forest-dwelling communities, was passed in 2006.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 25 Nov 2021 S2"]},{"id":"q1283","q":"Teak is the most prominent species of which type of forest in India?","o":["Tropical deciduous forest","Tropical evergreen forest","Thorn forests and scrubs","Montane forest"],"a":0,"x":"Teak is the most important species of India's tropical deciduous (monsoon) forests, along with sal, sandalwood and bamboo.","e":"Tropical deciduous forests are India's most widespread forest type.","src":["PRT 10 Apr 2026 S2"]},{"id":"q1378","q":"Which of the following national parks is known for the lesser panda (red panda)?","o":["Bandipur National Park","Jim Corbett National Park","Nagarhole National Park","Singalila National Park"],"a":3,"x":"Singalila National Park in Darjeeling, West Bengal, is known for the red panda (lesser panda). Bandipur and Nagarhole are in Karnataka; Jim Corbett in Uttarakhand.","e":"The red panda is Sikkim's state animal.","src":["TGT 24 Jun 2023 S2"]},{"id":"q1538","q":"Since 1986, in which IUCN category has the Indian bison been listed because of its declining population?","o":["Near Threatened","Critically Endangered","Vulnerable","Extinct in the Wild"],"a":2,"x":"The Indian bison (gaur) has been listed as Vulnerable on the IUCN Red List since 1986 because its population is falling.","e":"The gaur is the largest wild cattle species.","src":["TGT 24 Aug 2025 S3"]},{"id":"q5042","q":"_________ are species which are only found in some particular areas usually isolated by natural or geographical barriers.","o":["Endangered Species","Rare Species","Extinct Species","Endemic Species"],"a":3,"x":"Endemic species are found only in a particular area, often isolated by natural barriers.","e":"","src":["TGT 26 Sep 2021 S1"]},{"id":"q5600","q":"Name the state and wildlife sanctuary which hosts the most number of one-horned rhinoceroses in the world?","o":["Kaziranga, Assam","Sariska, Rajasthan","Jim Corbett National Park, Uttarakhand","Gulmarg National Park, Jammu and Kashmir"],"a":0,"x":"Kaziranga National Park in Assam has the world's largest population of one-horned rhinoceroses.","e":"","src":["TGT 30 Nov 2021 S1"]},{"id":"q5705","q":"The Nokrek National Park is located in which of the following states?","o":["Manipur","Sikkim","Meghalaya","Mizoram"],"a":2,"x":"Nokrek National Park is in the Garo Hills of Meghalaya.","e":"","src":["TGT 4 Sep 2021 S2"]},{"id":"q5986","q":"The Vikramshila Wildlife Sanctuary is located in ______.","o":["Uttarakhand","Rajasthan","Bihar","Kerala"],"a":2,"x":"The Vikramshila Gangetic Dolphin Sanctuary is in Bhagalpur, Bihar.","e":"","src":["TGT 8 Sep 2021 S1"]},{"id":"q7577","q":"Which of the following tree is found in coniferous forests? I. Chir II. Pine III. Ash","o":["I and II","II and III","I and III","I, II and III"],"a":0,"x":"Chir and pine are coniferous trees; ash is a deciduous tree.","e":"","src":["TGT 8 Aug 2021"]},{"id":"q8023","q":"Vultures in the Indian subcontinent were dying of kidney failure shortly after scavenging livestock treated with __________.","o":["omeprazole","diclofenac","metformin","lisinopril"],"a":1,"x":"India's vultures died of kidney failure after eating carcasses of cattle treated with the painkiller diclofenac.","e":"","src":["TGT 6 Jul 2023 S2"]},{"id":"q9825","q":"Nagarahole National Park is an important tiger reserve in _______ and is a major hub of conservation under Project Tiger and Project Elephant.","o":["Karnataka","Kerala","Telangana","Odisha"],"a":0,"x":"Nagarahole (Rajiv Gandhi) National Park is a tiger reserve in Karnataka.","e":"","src":["TGT 23 Aug 2025 S3"]},{"id":"q0785","q":"According to the Forest Survey Report, 2021, which of the following forest areas has seen an increase of 17 square kilometres compared to the previous assessment?","o":["Montane","Thorn","Tropical deciduous","Mangrove"],"a":3,"x":"The India State of Forest Report 2021 showed mangrove cover up by 17 sq km over the 2019 assessment, to 4,992 sq km.","e":"West Bengal (Sundarbans) has the largest mangrove cover, then Gujarat.","src":["PGT 11 Jul 2025 S1"]},{"id":"q6474","q":"Which among the following is the largest national park in India?","o":["Kaziranga National Park","Papikonda National Park","Hemis National Park","Keibul Lamjao National Park"],"a":2,"x":"Hemis National Park in Ladakh is India's largest national park.","e":"","src":["PGT 30 Jul 2021 S2"]},{"id":"q6680","q":"Anamudi Shola National Park is located in which of the following states?","o":["Kerala","Karnataka","Tamil Nadu","Maharashtra"],"a":0,"x":"Anamudi Shola National Park is in Idukki district, Kerala.","e":"","src":["PGT 30 Jul 2021 S2"]},{"id":"q9562","q":"In which of the following states Hazaribagh National Park is located?","o":["Tamil Nadu","Uttar Pradesh","Assam","Jharkhand"],"a":3,"x":"Hazaribagh National Park is in Jharkhand.","e":"","src":["PGT 28 Jun 2021 S1"]},{"id":"q1635","q":"Which of the following tree is found in tropical evergreen forests in India? I. Ebony II. Mahogany","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Ebony and mahogany grow in tropical evergreen forests.","e":"","src":["Senior Scientific Assistant (Lie-Detection) 10 Oct 2021 S1"]},{"id":"q3729","q":"When was Save Silent Valley movement held?","o":["1975","1974","1972","1973"],"a":3,"x":"The Save Silent Valley movement in Kerala began in 1973.","e":"","src":["Technical Assistant (Modern Office Practice) English 21 Oct 2021 S2"]},{"id":"q3965","q":"The Ramsar Wetlands Convention took place in ______ on 2 February, 1971.","o":["Iran","Iraq","Turkey","Egypt"],"a":0,"x":"The Ramsar Convention on wetlands was signed at Ramsar, Iran, on 2 February 1971.","e":"","src":["Trained Graduate Teacher (Deaf & Dumb) Tier-I 22 Nov 2021 S2"]},{"id":"q6710","q":"Which of the following tree belongs to tropical deciduous forest? I. Shisham II. Keora","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Shisham grows in tropical deciduous forests; keora is a mangrove tree.","e":"","src":["Investigator 26 Jul 2021"]},{"id":"q8159","q":"Bhadra Wildlife Sanctuary is located in which of the following states?","o":["Tamil Nadu","Goa","Telangana","Karnataka"],"a":3,"x":"Bhadra Wildlife Sanctuary is in Karnataka.","e":"","src":["Junior Engineer (Civil) or Section Officer (Civil) 27 Jun 2022 S2"]},{"id":"q8714","q":"In which state was the ‘Beej BachaoAndolan’ (Save the Seed Movement) started in the 1980s?","o":["Uttarakhand","Rajasthan","Kerala","Mizoram"],"a":0,"x":"The Beej Bachao Andolan (Save the Seeds Movement) began in Uttarakhand in the 1980s.","e":"","src":["Tailor Master 25 Jun 2023 S3"]}]},{"id":"pollution","n":"Pollution","qs":[{"id":"q0733","q":"Which one of the following should not be added to convert waste to compost in a compost pit?","o":["Leaves","Microorganisms","Plastic items","Water"],"a":2,"x":"Plastic should not go into a compost pit: it is non-biodegradable. Leaves, water and microorganisms help composting.","e":"Vermicomposting uses red wiggler earthworms.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q2072","q":"Which of the following is NOT an organic impurity?","o":["Oil","Nitrates","Human farces","Animal waste"],"a":1,"x":"Nitrates are inorganic impurities. Oil, human faeces and animal waste are organic impurities in water.","e":"Organic = carbon-based matter from living things.","src":["Junior Clerk 13 Nov 2021 S1"]},{"id":"q2668","q":"Which of the following is a by product of wastewater treatment? I. Sludge II. Biogas","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Sewage treatment produces sludge, which is broken down by bacteria to give biogas; both are by-products (NCERT Class 7).","e":"Biogas from sludge can run the plant.","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q6861","q":"When the pH value of rain water is measured as less than _____, it is known as acid rain.","o":["9.4","8.6","11.2","5.6"],"a":3,"x":"Rain with a pH below 5.6 is called acid rain.","e":"","src":["Stenographer 14 Aug 2021"]},{"id":"q7000","q":"Environment Protection Act was passed in the year _________.","o":["1986","1982","1976","1980"],"a":0,"x":"The Environment (Protection) Act was passed in 1986, after the Bhopal gas tragedy.","e":"","src":["Stenographer 14 Aug 2021"]},{"id":"q3598","q":"What does treatment of wastewater involve?","o":["Physical and Chemical processes only","Physical and Biological processes only","Chemical and Biological processes only","Physical, Chemical and Biological processes"],"a":3,"x":"Wastewater treatment uses physical (screening, settling), chemical (chlorination) and biological (bacteria breaking down waste) processes.","e":"","src":["Fire Operator 20 Apr 2021 S1"]},{"id":"q4290","q":"What is rapid increase in the population of algae in an aquatic system called?","o":["Eutrophication","Biomagnification","Thermal pollution","Algal Bloom"],"a":3,"x":"A rapid increase in algae in water is an algal bloom; eutrophication is the nutrient enrichment that causes it.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S2"]},{"id":"q4291","q":"_____________ is an approach to sanitation provision which safely reuses excreta in agriculture.","o":["Ecological sanitation","Solid waste management","Sanitary landfill","Circular sanitation"],"a":0,"x":"Ecological sanitation (ecosan) treats human excreta safely and reuses it as manure in farming.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S2"]},{"id":"q4381","q":"Which is the first step in preliminary sewage treatment?","o":["Grit Chamber","Screening","Primary sedimentation tank","Settling tank"],"a":1,"x":"Screening, which removes large floating objects, is the first step of sewage treatment; grit removal follows.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S1"]},{"id":"q4545","q":"Hair and body sprays release which of these particles into the atmosphere?","o":["Aerosols","CFC's (chlorofluorocarbons)","Ozone","Water Vapour"],"a":0,"x":"Hair and body sprays release aerosols (fine droplets) into the air.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 25 Nov 2021 S1"]},{"id":"q4620","q":"Methylmercury poisoning is the cause of which of the following diseases?","o":["Ischemic heart disease","Blackfoot disease","Minamata disease","Arsenicosis"],"a":2,"x":"Minamata disease is caused by methylmercury poisoning; it was first found at Minamata, Japan, in 1956.","e":"Itai-itai: cadmium; Blackfoot: arsenic.","src":["Fee Collector Sub Inspector Auction Recorder 25 Nov 2021 S2"]},{"id":"q1205","q":"Which of the following fuels causes the most pollution?","o":["Kerosene","CNG","Petrol","LNG"],"a":0,"x":"Among these, kerosene pollutes the most: it burns with soot, smoke and harmful gases. CNG and LNG are the cleanest fossil fuels.","e":"Delhi's buses switched to CNG in 2002 on Supreme Court orders.","src":["PRT 31 Mar 2026 S2"]},{"id":"q1518","q":"What is the revised PM10 levels reduction target of the National Clean Air Program (NCAP) by 2025-26 as compared to the baseline year of 2017-18?","o":["Up to 50%","Up to 40%","Up to 60%","Up to 30%"],"a":1,"x":"Under the National Clean Air Programme (launched 2019), the revised target is a cut of up to 40% in PM10 levels by 2025-26 from the 2017-18 baseline, in 131 non-attainment cities.","e":"The original target was 20–30% by 2024.","src":["TGT 24 Aug 2025 S1"]},{"id":"q3541","q":"Which of the following statement is correct? I. CO2 is not a greenhouse gas. II. Water which is purified and fit for drinking is known as potable water.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":1,"x":"CO₂ is a greenhouse gas, so I is wrong; water fit for drinking is called potable water.","e":"","src":["TGT 1 Oct 2021 S2"]},{"id":"q3570","q":"Which of the following statement is correct? I. By-products of waste water treatment are sludge and biogas. II. Sewage is a solid waste.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Sludge and biogas are by-products of wastewater treatment; sewage is liquid waste, not solid.","e":"","src":["TGT 1 Oct 2021 S3"]},{"id":"q5203","q":"Which one of the following fossil fuels is considered environment friendly?","o":["Natural Gas","Coal","Petroleum","Kerosene"],"a":0,"x":"Natural gas is the cleanest-burning fossil fuel, so it is considered environment friendly.","e":"","src":["TGT 27 Sep 2021 S1"]},{"id":"q3078","q":"What is the Biochemical Oxygen Demand (BOD) of clean water?","o":["Less than 5 ppm","Less than 6 ppm","Less than 6.5 ppm","Less than 6.9 ppm"],"a":0,"x":"Clean water has a biochemical oxygen demand of less than 5 ppm.","e":"","src":["Draftsman 17 Oct 2021 S1"]},{"id":"q4215","q":"Which of the following is the main ozone-destroying gas?","o":["Nitrous oxide","Carbon dioxide","Chlorofluorocarbon","Perfluoroisobutylene"],"a":2,"x":"Chlorofluorocarbons (CFCs) are the main ozone-destroying gases.","e":"","src":["Technical Assistant (Civil) 23 Oct 2021 S2"]}]},{"id":"climate","n":"Climate Change and Treaties","qs":[{"id":"q0123","q":"What is the primary purpose of the Kyoto Protocol, an international treaty related to environmental sustainability?","o":["To increase industrial waste production","To reduce greenhouse gas emissions","To encourage over-exploitation of natural resources","To promote deforestation"],"a":1,"x":"The Kyoto Protocol (adopted 1997, in force 2005) set binding greenhouse-gas cuts for developed countries under the UNFCCC.","e":"The Paris Agreement (2015) replaced it with pledges from all countries.","src":["ASO 19 Aug 2025 S2"]},{"id":"q2153","q":"Which of the following statements is true regarding HFCs?","o":["It contains chlorine","It is not categorised as a greenhouse gas","They harm ozone layer more than CFC","They are used in air conditioners"],"a":3,"x":"Hydrofluorocarbons (HFCs), which replaced CFCs, are used in air conditioners and refrigerators. They have no chlorine and do not harm the ozone layer, but they are powerful greenhouse gases.","e":"The Kigali Amendment (2016) phases down HFCs.","src":["Junior Clerk 13 Nov 2021 S3"]},{"id":"q4046","q":"When was the Kyoto Protocol adopted?","o":["1976","1989","1982","1997"],"a":3,"x":"The Kyoto Protocol, setting greenhouse gas cuts for developed countries, was adopted in 1997 and came into force in 2005.","e":"","src":["Stenographer 23 Apr 2021 S1"]},{"id":"q10120","q":"Accumulation of high concentration of ______ has led to the phenomenon of global warming.","o":["Nitrogen","Carbon dioxide","Carbon monoxide","Oxygen"],"a":1,"x":"Rising carbon dioxide concentration is the main cause of global warming.","e":"","src":["Assistant Superintendent 20 Jul 2024 S3"]},{"id":"q4384","q":"Name the climatic cycle in Pacific Ocean with global impact on weather pattern?","o":["El Nino Effect","Global Warming","Greenhouse effect","Milankovitch cycle"],"a":0,"x":"El Niño is a periodic warming of the eastern Pacific Ocean that changes weather worldwide, including weakening India's monsoon.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S1"]},{"id":"q5695","q":"The ozone layer helps to protect life from which harmful radiation?","o":["Beta radiation","Ultraviolet radiation","RF radiation","Ultrared radiation"],"a":1,"x":"The ozone layer protects life from the Sun's harmful ultraviolet radiation.","e":"","src":["TGT 4 Sep 2021 S1"]},{"id":"q7621","q":"Which of the following is not a direct Green House Gas?","o":["Methane","Carbon Dioxide","Nitrous Oxide","Hydrogen"],"a":3,"x":"Hydrogen is not a direct greenhouse gas; methane, CO₂ and nitrous oxide are.","e":"","src":["PGT 17 Jul 2021"]},{"id":"q2231","q":"Which of the following country is now a Carbon negative country?","o":["Nepal","Finland","Norway","Bhutan"],"a":3,"x":"Bhutan is a carbon-negative country.","e":"","src":["Laboratory Assistant (Lie Detection) 13 Sep 2021 S1"]},{"id":"q6716","q":"World Earth Day is celebrated on April ______.","o":["22","28","10","16"],"a":0,"x":"World Earth Day is observed on 22 April.","e":"","src":["Investigator 26 Jul 2021"]}]}]});
